$t['Automatic setup creates the webhook for this site URL only, or adds the missing events to it and keeps any other events. It saves the Webhook ID used to verify signatures. It never deletes webhooks, never touches other URLs and never changes the app permissions.'] = 'ההגדרה האוטומטית יוצרת את ה-webhook עבור כתובת ה-URL של אתר זה בלבד, או מוסיפה לו את האירועים החסרים ושומרת על כל שאר האירועים. היא שומרת את מזהה ה-Webhook המשמש לאימות חתימות. היא לעולם אינה מוחקת webhooks, אינה נוגעת בכתובות URL אחרות ואינה משנה את הרשאות האפליקציה.';
$t['Automatic setup needs Webhook Endpoints: Write. It creates the webhook and securely saves its new signing secret, or enables the existing endpoint and adds missing events. It preserves existing events and does not replace endpoints or change API key permissions.'] = 'ההגדרה האוטומטית דורשת Webhook Endpoints: Write. היא יוצרת את ה-webhook ושומרת באופן מאובטח את סוד החתימה החדש שלו, או מפעילה את נקודת הקצה הקיימת ומוסיפה אירועים חסרים. היא שומרת על האירועים הקיימים ואינה מחליפה נקודות קצה או משנה הרשאות של מפתח ה-API.';
