$t['The <a href=\'{videoLink}\'>{videoName}</a> video was reported as inappropriate from {user} '] = 'ה <a href=\'{videoLink}\'>{videoName}</a> וידאו דווח כבלתי פרופורציונלי מ- {user} ';
