$t['The change could not be saved'] = 'לא ניתן היה לשמור את השינוי';
$t['The check could not finish. Reload the page and try again.'] = 'הבדיקה לא הסתיימה. טען מחדש את הדף ונסה שוב.';
$t['The comment is empty'] = 'The comment is empty';
$t['The commit identifies the Git revision checked out on this server; local file edits are not included. A Git tag is shown when one points directly to that commit.'] = 'ה-commit מזהה את גרסת Git הפעילה בשרת זה; עריכות מקומיות בקבצים אינן נכללות. תגית Git מוצגת כאשר היא מצביעה ישירות על אותו commit.';
$t['The Companion Chat service is not available right now. Ask your site administrator to check the AI plugin connection.'] = 'שירות Companion Chat אינו זמין כרגע. בקש ממנהל האתר לבדוק את החיבור של תוסף ה-AI.';
$t['The connection could not be renewed. Please reconnect your account.'] = 'לא ניתן היה לחדש את החיבור. חבר מחדש את החשבון שלך.';
$t['The connection expired and could not be renewed. Please reconnect your account.'] = 'תוקף החיבור פג ולא ניתן היה לחדשו. חבר מחדש את החשבון שלך.';
$t['The connection to the destination was dropped mid-stream. This may be a temporary network issue; FFMPEG will try to reconnect.'] = 'החיבור ליעד נותק באמצע השידור. ייתכן שזו בעיית רשת זמנית; FFMPEG ינסה להתחבר מחדש.';
$t['The connection to YouTube was interrupted. The upload was paused and can be resumed.'] = 'החיבור ל-YouTube הופרע. ההעלאה הושהתה וניתן לחדש אותה.';
$t['The connection was interrupted. Check your account before retrying this subscription.'] = 'החיבור הופרע. בדוק את החשבון שלך לפני ניסיון חוזר של מינוי זה.';
$t['The connection was renewed.'] = 'החיבור חודש.';
$t['The connection window was closed before the authorization finished. No account was connected.'] = 'חלון החיבור נסגר לפני שההרשאה הושלמה. לא חובר אף חשבון.';
$t['The converted files were kept. Contact the site administrator to retry the transfer; you do not need to upload the video again.'] = 'הקבצים שהומרו נשמרו. פנה למנהל האתר כדי לנסות שוב את ההעברה; אין צורך להעלות את הסרטון מחדש.';
$t['The converted video could not be sent back to this site.'] = 'לא ניתן היה לשלוח את הסרטון שהומר חזרה לאתר זה.';
$t['The customers of the selected card. Search, sort, copy the e-mails or export everything to a spreadsheet.'] = 'הלקוחות של הכרטיס שנבחר. חפש, מיין, העתק את כתובות הדוא"ל או ייצא הכול לגיליון אלקטרוני.';
$t['The daily YouTube upload quota of this website was reached. Uploads become available again after midnight Pacific Time. Please try again later.'] = 'מכסת ההעלאות היומית ל-YouTube של אתר זה נוצלה. ההעלאות יתאפשרו שוב אחרי חצות לפי שעון האוקיינוס השקט. נסה שוב מאוחר יותר.';
$t['The database version changes only when a database migration is applied. It is not expected to match the release tag or commit.'] = 'גרסת מסד הנתונים משתנה רק כאשר מוחלת הגירה של מסד הנתונים. אין לצפות שתתאים לתגית הגרסה או ל-commit.';
$t['The default'] = 'ברירת המחדל';
$t['The destination RTMP server refused the connection. Check the stream URL and make sure the server is online.'] = 'שרת ה-RTMP של היעד דחה את החיבור. בדוק את כתובת השידור וודא שהשרת מקוון.';
$t['The destination server requires authentication. Check the stream key.'] = 'שרת היעד דורש אימות. בדוק את מפתח השידור.';
$t['The destination server returned 403. The stream key may be invalid or expired.'] = 'שרת היעד החזיר 403. ייתכן שמפתח השידור אינו תקף או שפג תוקפו.';
$t['The destination video was removed or this account cannot edit it. Check the video and account access on the site.'] = 'סרטון היעד הוסר או שחשבון זה אינו יכול לערוך אותו. בדוק את הסרטון ואת הגישה לחשבון באתר.';
$t['The download is controlled by the system, there is nothing to check on the user'] = 'ההורדה נשלטת על ידי המערכת, אין מה לבדוק על המשתמש';
$t['The download permission is site wide, so there is nothing to check on the video'] = 'הרשאת ההורדה חלה על כל האתר, ולכן אין מה לבדוק בסרטון';
$t['The download permission is site wide, so there is nothing to check onthe video'] = 'הרשאת ההורדה היא רחבה באתר, כך שאין מה לבדוק בסרטון';
$t['The email is invalid'] = 'האימייל אינו חוקי';
$t['The encoder could not download the original file.'] = 'המקודד לא הצליח להוריד את הקובץ המקורי.';
$t['The encoder could not find this video on the site.'] = 'המקודד לא מצא את הסרטון הזה באתר.';
$t['The encoder did not confirm that the video was added to the queue. Please retry.'] = 'המקודד לא אישר שהסרטון נוסף לתור. נסה שוב.';
$t['The encoder is running out of disk space'] = 'שטח הדיסק של המקודד עומד להיגמר';
$t['The encoder reported an unexpected error.'] = 'המקודד דיווח על שגיאה לא צפויה.';
$t['The encoding process stopped unexpectedly, and the automatic retries also failed.'] = 'תהליך הקידוד נעצר באופן בלתי צפוי, וגם הניסיונות החוזרים האוטומטיים נכשלו.';
$t['The encoding queue is stalled'] = 'תור הקידוד תקוע';
$t['The event purchase could not be completed. Your wallet payment was not deducted. Check your balance before trying again.'] = 'לא ניתן היה להשלים את רכישת האירוע. התשלום מהארנק שלך לא נוכה. בדוק את היתרה שלך לפני שתנסה שוב.';
$t['The file could not be converted. It may be damaged or use a format the encoder does not support.'] = 'לא ניתן היה להמיר את הקובץ. ייתכן שהוא פגום או בפורמט שהמקודד אינו תומך בו.';
$t['The file must be an .vtt file!'] = 'הקובץ חייב להיות קובץ.vtt!';
$t['The file must be an .vtt or .srt file!'] = 'הקובץ חייב להיות קובץ .vtt או .srt!';
$t['The final charge uses the duration measured during processing. A connected Marketplace wallet is required.'] = 'החיוב הסופי מבוסס על משך הזמן שנמדד במהלך העיבוד. נדרש ארנק Marketplace מחובר.';
$t['The following movie contains materials that are not suitable for children 17 and under.'] = 'הסרט הבא מכיל תכנים שאינם מתאימים לילדים בני 17 ומטה.';
$t['The following movie contains materials that may not be suitable for children 17 and under.'] = 'הסרט הבא מכיל תכנים שייתכן שאינם מתאימים לילדים בני 17 ומטה.';
$t['The form to signup will not exists'] = 'הטופס להרשמה לא יהיה קיים';
$t['The gift code has been canceled. If this is unexpected, please contact our support team.'] = 'קוד המתנה בוטל. אם הדבר אינו צפוי, פנה לצוות התמיכה שלנו.';
$t['The gift code is currently inactive. Please check back later or contact support.'] = 'קוד המתנה אינו פעיל כרגע. בדוק שוב מאוחר יותר או פנה לתמיכה.';
$t['The information above corresponds to our official records and confirms the authenticity of this certificate.'] = 'המידע שלעיל תואם לרישומים הרשמיים שלנו ומאשר את אמיתות תעודה זו.';
$t['The input stream contains invalid data. The source HLS may not be ready yet or the stream was interrupted.'] = 'זרם הקלט מכיל נתונים לא תקינים. ייתכן שמקור ה-HLS עדיין אינו מוכן או שהשידור הופרע.';
$t['The installed PHP package lists both fixes, but this web process still runs the copy loaded before the update. Restart Apache or PHP-FPM.'] = 'חבילת PHP המותקנת כוללת את שני התיקונים, אך תהליך האינטרנט הזה עדיין מריץ את העותק שנטען לפני העדכון. הפעל מחדש את Apache או את PHP-FPM.';
$t['Their last plans add up to %s'] = 'התוכניות האחרונות שלהם מסתכמות ב-%s';
$t['The list was limited to the first %s results.'] = 'הרשימה הוגבלה ל-%s התוצאות הראשונות.';
$t['The live service could not complete the request. Please try again.'] = 'שירות השידור החי לא הצליח להשלים את הבקשה. נא לנסות שוב.';
$t['The live that was still being sent to this destination was stopped.'] = 'השידור החי שעדיין נשלח ליעד זה הופסק.';
$t['Theme for Style:'] = 'ערכת נושא עבור סגנון:';
$t['Themes'] = 'ערכות נושא';
$t['The number of lines in both columns must be the same'] = 'מספר השורות בשתי העמודות חייב להיות זהה';
$t['The original file for this video does not exists anymore'] = 'הקובץ המקורי של סרטון זה אינו קיים עוד';
$t['The Permissions Plugin is not installed. Please install it if you want to customize the permissions.'] = 'תוסף ההרשאות אינו מותקן. נא התקן אותו אם ברצונך להתאים אישית את ההרשאות.';
$t['The plugin is disabled'] = 'התוסף אינו זמין';
$t['The program is empty'] = 'התוכנית ריקה';
$t['The purchase could not be completed. Your wallet payment was not deducted. Check your balance before trying again.'] = 'לא ניתן היה להשלים את הרכישה. התשלום מהארנק שלך לא נוכה. בדוק את היתרה שלך לפני שתנסה שוב.';
$t['There\'s an unknown status associated with this gift code. Please contact support for assistance.'] = 'לקוד המתנה הזה משויך סטטוס לא ידוע. נא לפנות לתמיכה לקבלת עזרה.';
$t['There, you can set'] = 'שם, אתה יכול להגדיר';
$t['There are no notifications'] = 'אין התראות';
$t['There are no upcoming events for this channel'] = 'אין אירועים קרובים לערוץ זה';
$t['There are various kinds of media you can integrate here. They are working different'] = 'ישנם סוגים שונים של מדיה אתה יכול לשלב כאן. הם עובדים אחרת.';
$t['The recover pass does not match!'] = 'כרטיס ההתאוששות אינו תואם!';
$t['The regular form to signin will not exist, if you check this will only have social login or LDAP option'] = 'הטופס הרגיל לכניסה לא יהיה קיים, אם תבדוק את זה יהיה רק כניסה חברתית או אפשרות LDAP';
$t['There is missing data to recover your password'] = 'אין נתונים חסרים כדי לשחזר את הסיסמה שלך';
$t['There is no Pay Per View plan yet. Create one in the Pay-Per-View plugin, PPV Plans tab.'] = 'עדיין אין תוכנית Pay Per View. צור אחת בתוסף Pay-Per-View, בלשונית PPV Plans.';
$t['There is no plan that can hold videos yet. Create one in the PPV Plans tab, then come back here.'] = 'עדיין אין תוכנית שיכולה להכיל סרטונים. צור אחת בלשונית PPV Plans, ואז חזור לכאן.';
$t['There is no streaming now'] = 'אין זרימה עכשיו';
$t['The release number and the AVideo database version are independent. Code update status is determined by commit history.'] = 'מספר הגרסה וגרסת מסד הנתונים של AVideo אינם תלויים זה בזה. מצב עדכון הקוד נקבע לפי היסטוריית ה-commits.';
$t['The request to the social network failed. Please try again later.'] = 'הבקשה לרשת החברתית נכשלה. נא לנסות שוב מאוחר יותר.';
$t['The restreamer server cannot reach the destination. Check network connectivity.'] = 'שרת ה-restreamer אינו מצליח להגיע ליעד. בדוק את חיבור הרשת.';
$t['The same alert is repeated at most every %s while the problem continues.'] = 'אותה התראה חוזרת לכל היותר פעם ב-%s כל עוד הבעיה נמשכת.';
$t['The same alert is repeated at most every few hours while the problem continues.'] = 'אותה התראה חוזרת לכל היותר פעם בכמה שעות כל עוד הבעיה נמשכת.';
$t['The selected camera or microphone is not available. Please choose another device.'] = 'המצלמה או המיקרופון שנבחרו אינם זמינים. נא לבחור מכשיר אחר.';
$t['The selected position is highlighted on a real page. Mobile preview changes only the ADs positions; the rest of the page uses your browser device.'] = 'המיקום שנבחר מודגש בעמוד אמיתי. תצוגה מקדימה לנייד משנה רק את מיקומי הפרסומות; שאר העמוד משתמש במכשיר הדפדפן שלך.';
$t['The selected position is outlined on a real page of your site and follows the position you choose below. Mobile preview changes only the ADs positions; the rest of the page uses your browser device.'] = 'המיקום שנבחר מסומן בקו מתאר בדף אמיתי באתר שלכם ומשתנה לפי המיקום שתבחרו למטה. התצוגה המקדימה לנייד משנה רק את מיקומי הפרסומות; שאר הדף משתמש במכשיר של הדפדפן שלכם.';
$t['The site is currently offline due to a database issue. We are working to resolve the problem as quickly as possible.'] = 'האתר אינו זמין כרגע עקב בעיה במסד הנתונים. אנו פועלים לפתור את הבעיה במהירות האפשרית.';
$t['The site is temporarily unavailable because the server\'s disk is full. We are working on this issue and will be back shortly.'] = 'האתר אינו זמין זמנית מכיוון שהדיסק של השרת מלא. אנו מטפלים בבעיה ונחזור בקרוב.';
$t['The site is undergoing maintenance as the server\'s disk is nearing capacity. We are addressing the issue and will be back shortly.'] = 'האתר נמצא בתחזוקה מכיוון שהדיסק של השרת מתקרב לקיבולת המלאה. אנו מטפלים בבעיה ונחזור בקרוב.';
$t['The site refused access. Renew the encoder account access and check its upload permissions.'] = 'האתר סירב לגישה. חדש את הגישה של חשבון המקודד ובדוק את הרשאות ההעלאה שלו.';
$t['The site will display only a login form to un authenticated users'] = 'האתר יציג רק טופס כניסה למשתמשים לא מאומתים';
$t['The source stream ended. If the live was stopped intentionally this is normal.'] = 'שידור המקור הסתיים. אם השידור החי הופסק במכוון, זה תקין.';
$t['The split is on: desktop visitors do not see this banner now, they see the left and right halves.'] = 'הפיצול פעיל: מבקרים במחשב אינם רואים כעת את הבאנר הזה, הם רואים את החצי השמאלי והימני.';
