$t['YouTube is receiving too many requests right now. Please wait a few minutes and try again.'] = 'YouTube מקבל יותר מדי בקשות כרגע. המתן מספר דקות ונסה שוב.';
$t['YouTube rejected the video because it does not follow the YouTube policies.'] = 'YouTube דחה את הסרטון כי הוא אינו עומד במדיניות של YouTube.';
$t['YouTube rejected the video because it is a duplicate of a video already on your channel.'] = 'YouTube דחה את הסרטון כי הוא כפילות של סרטון שכבר נמצא בערוץ שלך.';
$t['YouTube rejected the video because it is longer than your channel allows. Verify your YouTube account to upload longer videos.'] = 'YouTube דחה את הסרטון כי הוא ארוך מהמותר בערוץ שלך. אמת את חשבון ה-YouTube שלך כדי להעלות סרטונים ארוכים יותר.';
$t['YouTube rejected the video because of a copyright claim.'] = 'YouTube דחה את הסרטון בגלל תביעת זכויות יוצרים.';
$t['YouTube returned an unexpected error. Please try again later. If the problem continues, contact the site administrator.'] = 'YouTube החזיר שגיאה לא צפויה. נסה שוב מאוחר יותר. אם הבעיה נמשכת, פנה למנהל האתר.';
$t['YouTube URL'] = 'כתובת URL של YouTube';
$t['You were disconnected because your account was used to log in from another device or location'] = 'התנתקת כי החשבון שלך שימש להתחברות ממכשיר או ממיקום אחר';
$t['You will be redirected to the following URL:'] = 'תועבר לכתובת ה-URL הבאה:';
